<?php
declare(strict_types=1);
namespace App\Upms;
use PDO;

/** Additional guards; the original 103 definitions are included without alteration. */
final class ChequeGuards
{
    public static function plan(string $runtime): array
    {
        if(!preg_match('/^money_rt_[0-9]+$/D',$runtime)) { throw new \RuntimeException('CHEQUE_ISOLATED_RUNTIME_REQUIRED'); }
        $rules=[];
        $add=static function($t,$event,$bad='TRUE') use(&$rules,$runtime) { $rules['upmscq_'.$t.'_'.strtolower($event)]=['table'=>$t,'event'=>$event,'body'=>"BEGIN IF SUBSTRING_INDEX(USER(),'@',1)='$runtime' AND ($bad) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='UPMS_CHEQUE_PROTECTED'; END IF; END"]; };
        foreach(array_keys(ChequeSchema::plan()['tables']) as $t) { foreach(['UPDATE','DELETE'] as $e) { $add($t,$e); } }
        foreach(['cheque_schema_receipts','cheque_issuing_banks'] as $t) { $add($t,'INSERT'); }
        $permission=static fn($p)=>"NOT EXISTS(SELECT 1 FROM users u JOIN user_roles ur ON ur.user_id=u.id JOIN role_permissions rp ON rp.role_code=ur.role_code WHERE u.id=NEW.actor_id AND u.enabled=1 AND rp.permission_code='$p')";
        $add('cheque_instruments','INSERT',$permission('cheques.receive')." OR NEW.reference NOT REGEXP '^[A-Z0-9][A-Z0-9_-]{2,99}$' OR NEW.number NOT REGEXP '^[1-9][0-9]{0,29}$' OR NEW.drawer_account_key NOT REGEXP '^[A-Z0-9]{6,34}$' OR CHAR_LENGTH(TRIM(NEW.drawer_name))<2 OR NEW.received_date>DATE(UTC_TIMESTAMP()+INTERVAL 5 HOUR) OR NOT EXISTS(SELECT 1 FROM v1_parties p WHERE p.id=NEW.client_id AND p.kind='CLIENT' AND p.active=1 AND BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.client_snapshot,'$.id'))=BINARY CAST(p.id AS CHAR) AND JSON_UNQUOTE(JSON_EXTRACT(NEW.client_snapshot,'$.name'))=p.name)");
        $prior="SELECT e.type FROM cheque_events e WHERE e.cheque_id=NEW.cheque_id ORDER BY e.ordinal DESC LIMIT 1";
        $date="SELECT MAX(e.date) FROM cheque_events e WHERE e.cheque_id=NEW.cheque_id";
        $bad="NEW.date>DATE(UTC_TIMESTAMP()+INTERVAL 5 HOUR) OR NEW.date<(SELECT c.received_date FROM cheque_instruments c WHERE c.id=NEW.cheque_id) OR NEW.date<COALESCE(($date),NEW.date) OR NEW.ordinal<>COALESCE((SELECT MAX(e.ordinal)+1 FROM cheque_events e WHERE e.cheque_id=NEW.cheque_id),1) OR NEW.previous_hash<>COALESCE((SELECT a.payload_hash FROM cheque_events e JOIN cheque_audit a ON a.event_id=e.id WHERE e.cheque_id=NEW.cheque_id ORDER BY e.ordinal DESC LIMIT 1),REPEAT('0',64)) OR CHAR_LENGTH(TRIM(NEW.reference))<3 OR CHAR_LENGTH(TRIM(NEW.reason))<10";
        $bad.=" OR NOT COALESCE(((NEW.type='RECEIVED' AND NEW.ordinal=1 AND NEW.date=(SELECT c.received_date FROM cheque_instruments c WHERE c.id=NEW.cheque_id)) OR (NEW.type='DEPOSITED' AND ($prior)='RECEIVED') OR (NEW.type IN('CLEARED','DISHONOURED') AND ($prior)='DEPOSITED') OR (NEW.type='RETURNED' AND ($prior) IN('RECEIVED','DEPOSITED','DISHONOURED')) OR (NEW.type='CANCELLED' AND ($prior)='RECEIVED')),FALSE)";
        foreach(['RECEIVED'=>'receive','DEPOSITED'=>'deposit','CLEARED'=>'clear','DISHONOURED'=>'dishonour','RETURNED'=>'dispose','CANCELLED'=>'dispose'] as $state=>$cap) { $bad.=" OR (NEW.type='$state' AND (".$permission('cheques.'.$cap).'))'; }
        $bad.=" OR (NEW.type<>'RECEIVED' AND CHAR_LENGTH(TRIM(NEW.evidence))<10) OR (NEW.type IN('DEPOSITED','CLEARED','DISHONOURED') AND NOT EXISTS(SELECT 1 FROM money_accounts a JOIN money_batches b ON b.to_account_id=a.id AND b.kind='OPENING' WHERE a.id=NEW.bank_id AND a.type='BANK' AND b.date<=NEW.date)) OR (NEW.type NOT IN('DEPOSITED','CLEARED','DISHONOURED') AND NEW.bank_id IS NOT NULL) OR (NEW.type<>'CLEARED' AND (NEW.document_id IS NOT NULL OR NEW.batch_id IS NOT NULL))";
        $bad.=" OR (NEW.type='CLEARED' AND (NEW.date<(SELECT c.cheque_date FROM cheque_instruments c WHERE c.id=NEW.cheque_id) OR NEW.bank_id<>(SELECT e.bank_id FROM cheque_events e WHERE e.cheque_id=NEW.cheque_id ORDER BY e.ordinal DESC LIMIT 1) OR (EXISTS(SELECT 1 FROM cheque_events e WHERE e.cheque_id=NEW.cheque_id AND e.actor_id=NEW.actor_id) AND (CHAR_LENGTH(TRIM(NEW.self_approval_reason))<10 OR NOT EXISTS(SELECT 1 FROM user_roles ur WHERE ur.user_id=NEW.actor_id AND ur.role_code='administrator'))) OR NOT EXISTS(SELECT 1 FROM cheque_instruments c JOIN v1_documents d ON d.id=NEW.document_id JOIN money_batches b ON b.id=NEW.batch_id WHERE c.id=NEW.cheque_id AND d.kind='CLIENT_PAYMENT' AND d.status='POSTED' AND d.date=NEW.date AND d.party_id=c.client_id AND d.total=c.amount AND JSON_UNQUOTE(JSON_EXTRACT(d.payload,'$.method'))='CHEQUE_CLEARED' AND BINARY JSON_UNQUOTE(JSON_EXTRACT(d.payload,'$.chequeSource.id'))=BINARY CAST(c.id AS CHAR) AND b.source_type='DOCUMENT' AND BINARY b.source_ref=BINARY CONCAT('UPMS-DOC:',d.id) AND b.kind='SOURCE_CREDIT' AND b.to_account_id=NEW.bank_id AND b.amount=c.amount AND b.actor_id=NEW.actor_id)))";
        $bad.=" OR (NEW.type='CLEARED' AND (NOT EXISTS(SELECT 1 FROM v1_documents o JOIN cheque_instruments c ON c.client_id=o.party_id WHERE c.id=NEW.cheque_id AND o.kind='CLIENT_OPENING' AND o.status='POSTED' AND o.date<=NEW.date) OR COALESCE((SELECT SUM(j.debit-j.credit) FROM v1_party_journal j JOIN cheque_instruments c ON c.client_id=j.party_id WHERE c.id=NEW.cheque_id),0)<0 OR EXISTS(SELECT 1 FROM v1_documents d JOIN cheque_instruments c ON c.client_id=d.party_id WHERE c.id=NEW.cheque_id AND d.status='POSTED' AND d.date>NEW.date) OR EXISTS(SELECT 1 FROM money_movements m JOIN money_batches b ON b.id=m.batch_id WHERE m.account_id=NEW.bank_id AND b.date>NEW.date)))";
        $add('cheque_events','INSERT',$bad);
        $add('cheque_audit','INSERT',"NEW.payload_hash NOT REGEXP '^[a-f0-9]{64}$' OR NOT EXISTS(SELECT 1 FROM cheque_events e WHERE e.id=NEW.event_id AND e.actor_id=NEW.actor_id AND e.created_at=NEW.created_at)");
        $add('cheque_clearances','INSERT',$permission('cheques.clear')." OR NEW.instrument_hash NOT REGEXP '^[a-f0-9]{64}$' OR NEW.event_hash NOT REGEXP '^[a-f0-9]{64}$' OR NEW.document_hash NOT REGEXP '^[a-f0-9]{64}$' OR NEW.batch_hash NOT REGEXP '^[a-f0-9]{64}$' OR NEW.movement_hash NOT REGEXP '^[a-f0-9]{64}$' OR NOT EXISTS(SELECT 1 FROM cheque_events e JOIN cheque_instruments c ON c.id=e.cheque_id JOIN cheque_audit a ON a.event_id=e.id JOIN money_movements m ON m.id=NEW.movement_id WHERE e.id=NEW.event_id AND e.type='CLEARED' AND e.cheque_id=NEW.cheque_id AND e.document_id=NEW.document_id AND e.batch_id=NEW.batch_id AND e.actor_id=NEW.actor_id AND e.created_at=NEW.created_at AND a.payload_hash=NEW.event_hash AND m.batch_id=NEW.batch_id AND m.account_id=e.bank_id AND m.delta=c.amount)");
        // No public draft/legacy path can invent clearance markers or a refund of a cleared cheque.
        foreach(['INSERT','UPDATE'] as $op) {
            $add('v1_documents',$op,"(JSON_UNQUOTE(JSON_EXTRACT(NEW.payload,'$.method'))='CHEQUE_CLEARED' AND (NEW.kind<>'CLIENT_PAYMENT' OR COALESCE(JSON_UNQUOTE(JSON_EXTRACT(NEW.payload,'$.chequeRecognitionVersion')),'')<>'uat2-v1' OR NOT EXISTS(SELECT 1 FROM cheque_instruments c JOIN cheque_events e ON e.cheque_id=c.id WHERE BINARY CAST(c.id AS CHAR)=BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.payload,'$.chequeSource.id')) AND BINARY CAST(e.id AS CHAR)=BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.payload,'$.chequeSource.depositEventId')) AND e.type='DEPOSITED' AND e.ordinal=(SELECT MAX(x.ordinal) FROM cheque_events x WHERE x.cheque_id=c.id) AND c.client_id=NEW.party_id AND c.amount=CAST(JSON_UNQUOTE(JSON_EXTRACT(NEW.payload,'$.amount')) AS DECIMAL(18,2)) AND NEW.date>=c.cheque_date AND NEW.date>=e.date AND BINARY CAST(e.bank_id AS CHAR)=BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.payload,'$.moneyAccountId'))))) OR (NEW.kind IN('FINANCIAL_REFUND','PAYMENT_REVERSAL') AND EXISTS(SELECT 1 FROM cheque_clearances x WHERE x.document_id=COALESCE(NEW.corrects_id,CAST(JSON_UNQUOTE(JSON_EXTRACT(NEW.payload,'$.originalId')) AS UNSIGNED))))");
        }
        $add('money_batches','INSERT',"(NEW.source_type='EXTERNAL' AND (LOWER(NEW.source_ref) LIKE 'upms-cheque:%' OR EXISTS(SELECT 1 FROM cheque_instruments c WHERE c.reference=NEW.source_ref))) OR (NEW.corrects_id IS NOT NULL AND EXISTS(SELECT 1 FROM cheque_clearances c WHERE c.batch_id=NEW.corrects_id))");
        if(ChequeExtras::enabled()) {
            $rules['upmscq_cheque_issuing_banks_insert']['body']="BEGIN IF SUBSTRING_INDEX(USER(),'@',1)='$runtime' AND NOT EXISTS(SELECT 1 FROM cheque_bank_creations b WHERE b.id=NEW.id AND BINARY b.code=BINARY NEW.code AND BINARY b.name=BINARY NEW.name) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='UPMS_CHEQUE_DIRECTORY_REQUIRED'; END IF; END";
            $rules=[...$rules,...ChequeExtras::guards($runtime)];
        }
        ksort($rules);return $rules;
    }
    public static function hash(string $runtime): string { return hash('sha256',json_encode(self::plan($runtime),JSON_THROW_ON_ERROR)); }
    public static function verify(PDO $pdo,string $runtime,?string $definer=null): array
    {
        return [...MoneyGuards::verify($pdo,$runtime,$definer,[...ExpenseGuards::plan($runtime),...EmployeeHaftaGuards::plan($runtime),...LaborExtensionGuards::plan($runtime),...self::plan($runtime)]),'expenseHash'=>ExpenseGuards::hash($runtime),'laborHash'=>EmployeeHaftaGuards::hash($runtime),'extensionHash'=>LaborExtensionGuards::hash($runtime),'chequeHash'=>self::hash($runtime),'chequeGuards'=>count(self::plan($runtime))];
    }
}
